function verifyAPIKey(req, res, next) {
	// ? Headers are available on req.headers. Express lowercases header names,
	// ? so a client can send `apikey` as the header name here.
	console.log(req.headers.apikey)

	// ? This pattern describes a version-4 UUID, the format generated by /keygen.
	// ? In a real application, the key would usually also be looked up in a database.
	const uuidRegex =
		/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

	const isKeyValid = uuidRegex.test(req.headers.apikey);

	if (!isKeyValid) {
		// ? Sending a response ends the request/response lifecycle.
		// ? return prevents this function from continuing to next() afterward.
		return res.status(403).json({message: "Forbidden"})
	}

	// ? A valid key allows the request to continue to the protected router.
	next()
}

module.exports = verifyAPIKey;
